def view(yaw):
    a = math.radians(yaw)
    focus = Vector((0,0,(785-405)*unit))
    camera.location = focus + Vector((4*math.sin(a),-4*math.cos(a),0))
    camera.rotation_euler = (focus-camera.location).to_track_quat("-Z","Y").to_euler()
